        int total = (int) customers.stream().filter(matching(filter)).count();
        queryLog.recordCount(total);
        return total;
    }

    private static Predicate<Customer> matching(CustomerFilter filter) {
        List<String> terms = filter.name().trim().isEmpty()
                ? List.of()
                : List.of(filter.name().trim().split("\\s+")).stream().map(CustomerRepository::fold).toList();
        Set<CustomerStatus> statuses = filter.statuses();
        return customer -> {
            if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
                return false;
            }
            if (terms.isEmpty()) {
                return true;
            }
            String firstName = fold(customer.firstName());
            String lastName = fold(customer.lastName());
            return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
        };
    }

    /** Case- and accent-insensitive folding, so {@code "mäkinen"} matches {@code "MAKINEN"}. */
    private static String fold(String value) {
