+                        .sorted(Comparator.comparingInt(CustomerStatus::ordinal))
+                        .map(CustomerStatus::name)
+                        .collect(Collectors.joining(","));
+                params.put("status", List.of(joined));
+            }
+
+            String query = new QueryParameters(params).getQueryString();
+            String url = basePath + (query.isEmpty() ? "" : "?" + query);
+            ui.getPage().getHistory().replaceState(null, url);
+        });
+    }
+
+    private static Set<CustomerStatus> parseStatuses(String raw) {
+        return raw.isBlank()
+                ? Set.of()
+                : Arrays.stream(raw.split(","))
+                        .map(String::trim)
+                        .filter(s -> !s.isEmpty())
+                        .map(CustomerStatus::valueOf)
+                        .collect(Collectors.toCollection(LinkedHashSet::new));
     }

